# ==================================================================
# Isotope lab correction — single-file Shiny app
# Thermo GasBench | Thermo EA | Sercon EA
#
# Run:  shiny::runApp("isotope_app")
#   or double-click run_isotope_app.command / .bat
# Regenerated by: Rscript dev/rebuild_app.R
# ==================================================================

# Install any missing CRAN packages (automatic; first launch may take a minute)
if (!isTRUE(getOption("isotope_app.pkgs_ok"))) {
  inst <- "install_packages.R"
  if (file.exists(inst)) {
    sys.source(inst, envir = new.env(parent = globalenv()))
  } else {
    pkgs <- c(
      "shiny", "dplyr", "ggplot2", "ggrepel", "readxl", "openxlsx", "DT",
      "stringr", "tidyr", "gridExtra"
    )
    options(repos = c(CRAN = "https://cloud.r-project.org"))
    miss <- pkgs[!vapply(pkgs, requireNamespace, quietly = TRUE, FUN.VALUE = logical(1))]
    if (length(miss)) {
      message("Installing missing packages: ", paste(miss, collapse = ", "))
      install.packages(miss)
    }
    options(isotope_app.pkgs_ok = TRUE)
  }
}

suppressPackageStartupMessages({
  library(shiny)
  library(dplyr)
  library(ggplot2)
  library(ggrepel)
  library(readxl)
  library(openxlsx)
  library(DT)
  library(stringr)
  library(tidyr)
  library(gridExtra)
})

`%||%` <- function(a, b) if (!is.null(a)) a else b

# ========== BEGIN common.R ==========
# ==================================================================
# common.R -- Shared helpers for isotope_app modules
# Colored tab CSS, outlier-box styles, plot/DT/workbook utilities.
# ==================================================================

# CSS for workflow tab colours + compact outlier checkbox panels.
# If `id` is given, selectors are scoped to `#id` (wrap module UI in
# tags$div(id = id, ...) so the scope matches).
isotope_tab_css <- function(id = NULL) {
  p <- if (is.null(id) || !nzchar(id)) "" else paste0("#", id, " ")
  paste0(
    "/* Bootstrap 3 — workflow: Intl (blue), Inhouse (orange), Samples (green), Coef (grey) */\n",
    p, ".tabbable > .nav-tabs > li:nth-child(1) > a { background-color: #bdd7ee; color: #1f4e79; }\n",
    p, ".tabbable > .nav-tabs > li:nth-child(2) > a { background-color: #fce4d6; color: #c65911; }\n",
    p, ".tabbable > .nav-tabs > li:nth-child(3) > a { background-color: #c6efce; color: #006100; }\n",
    p, ".tabbable > .nav-tabs > li:nth-child(4) > a { background-color: #d9d9d9; color: #595959; }\n",
    p, ".tabbable > .nav-tabs > li.active > a,\n",
    p, ".tabbable > .nav-tabs > li.active > a:hover,\n",
    p, ".tabbable > .nav-tabs > li.active > a:focus { font-weight: 700; border-bottom-color: transparent; }\n",
    "/* Bootstrap 5 / bslib */\n",
    p, ".nav-tabs .nav-item:nth-child(1) .nav-link { background-color: #bdd7ee; color: #1f4e79; }\n",
    p, ".nav-tabs .nav-item:nth-child(2) .nav-link { background-color: #fce4d6; color: #c65911; }\n",
    p, ".nav-tabs .nav-item:nth-child(3) .nav-link { background-color: #c6efce; color: #006100; }\n",
    p, ".nav-tabs .nav-item:nth-child(4) .nav-link { background-color: #d9d9d9; color: #595959; }\n",
    p, ".nav-tabs .nav-item .nav-link.active { font-weight: 700; }\n",
    "/* Shaded panel around the whole outlier section */\n",
    p, ".outlier-panel { border: 1px solid #ccc; border-radius: 6px; padding: 8px 10px;\n",
    "                 margin: 8px 0 12px 0; background: #f0f0f0; }\n",
    p, ".outlier-panel > .shiny-input-checkbox { margin-top: 0; margin-bottom: 8px; }\n",
    p, ".outlier-panel > .shiny-input-checkbox label { font-size: 12px; font-weight: 500; }\n",
    "/* Compact outlier checkbox panels */\n",
    p, ".outlier-box { max-height: 160px; overflow-y: auto; margin-bottom: 6px;\n",
    "               border: 1px solid #ddd; border-radius: 4px; padding: 4px 8px; background: #fafafa; }\n",
    p, ".outlier-box .shiny-options-group label { font-weight: normal; font-size: 12px;\n",
    "               margin: 0 8px 2px 0; display: inline-block; white-space: nowrap; }\n",
    p, ".outlier-box .control-label { font-size: 12px; font-weight: 600; margin-bottom: 2px; }\n",
    p, ".outlier-box .checkbox { margin-top: 0; margin-bottom: 0; }\n",
    p, ".outlier-heading { font-size: 14px; font-weight: 600; margin: 0 0 6px 0; }\n"
  )
}

clean_idx <- function(idx, n) {
  idx <- as.integer(idx)
  idx[!is.na(idx) & idx >= 1 & idx <= n]
}

# Prefer isotope-specific exclude list; else fall back to shared legacy list.
resolve_excl <- function(specific, shared = integer(0)) {
  if (!is.null(specific)) specific else shared
}

# Stamp outlier_C + outlier_O/N and combined `outlier` (Yes if either).
stamp_dual_outliers <- function(df, excl_a, excl_b, col_a, col_b) {
  n <- nrow(df)
  df[[col_a]] <- "No"
  df[[col_b]] <- "No"
  ea <- clean_idx(excl_a, n)
  eb <- clean_idx(excl_b, n)
  if (length(ea) > 0) df[[col_a]][ea] <- "Yes"
  if (length(eb) > 0) df[[col_b]][eb] <- "Yes"
  df$outlier <- ifelse(df[[col_a]] == "Yes" | df[[col_b]] == "Yes", "Yes", "No")
  df
}

# Compact dual isotope outlier checkbox panels (same row indices / labels).
outlier_dual_checks_ui <- function(ns, id_a, id_b, label_a, label_b, n, ids) {
  if (n < 1) return(NULL)
  lbls <- paste0(seq_len(n), ": ", ids)
  choices <- setNames(as.list(seq_len(n)), lbls)
  tagList(
    tags$div(class = "outlier-box",
      checkboxGroupInput(ns(id_a), label_a,
                         choices = choices, selected = character(0), inline = TRUE)),
    tags$div(class = "outlier-box",
      checkboxGroupInput(ns(id_b), label_b,
                         choices = choices, selected = character(0), inline = TRUE))
  )
}

# Single shared outlier checkbox panel (combined mode).
outlier_single_checks_ui <- function(ns, input_id, label, n, ids) {
  if (n < 1) return(NULL)
  lbls <- paste0(seq_len(n), ": ", ids)
  choices <- setNames(as.list(seq_len(n)), lbls)
  tags$div(class = "outlier-box",
    checkboxGroupInput(ns(input_id), label,
                       choices = choices, selected = character(0), inline = TRUE))
}

# Shaded sidebar block: heading + split toggle + intl/mass uiOutputs.
# pair_label e.g. "C / O" (GasBench) or "C / N" (EA).
outlier_sidebar_ui <- function(ns, pair_label = "C / N") {
  tags$div(class = "outlier-panel", `data-guide` = "outliers",
    tags$div(class = "outlier-heading", "Exclude outliers"),
    checkboxInput(ns("split_outliers"),
                  paste0("Split by isotope (", pair_label, ")"),
                  value = FALSE),
    tags$div(`data-guide` = "intl-outliers", uiOutput(ns("intl_checks"))),
    tags$div(`data-guide` = "inhouse-outliers", uiOutput(ns("mass_checks")))
  )
}

# Which exclude list to use for one isotope given combine/split mode.
pick_excl <- function(split, shared, specific) {
  if (isTRUE(split)) specific else shared
}

# Significant decimal places as written (trailing zeros do not count).
# Excel-as-text often dumps "1.2340000000000002" — ignore that noise.
decimals_from_text <- function(x) {
  s <- trimws(as.character(x))
  s <- s[!(is.na(s) | !nzchar(s) | s %in% c("NA", "NaN", "NULL", "#N/A"))]
  if (!length(s)) return(NA_integer_)
  s <- gsub(",", ".", s, fixed = TRUE)
  s <- sub("^[+]+", "", s)
  ok <- grepl("^-?[0-9]*\\.?[0-9]+$", s)
  s <- s[ok]
  if (!length(s)) return(NA_integer_)
  nd <- vapply(s, function(v) {
    if (!grepl(".", v, fixed = TRUE)) return(0L)
    frac <- sub("0+$", "", strsplit(v, ".", fixed = TRUE)[[1]][2])
    nchar(frac)
  }, integer(1))
  nd <- nd[nd <= 6L]
  if (!length(nd)) return(NA_integer_)
  as.integer(names(sort(table(nd), decreasing = TRUE))[1])
}

# Numeric fallback: smallest d that matches, then the most common of those (cap 4).
decimals_from_numeric <- function(x, fallback = 3L, max_d = 4L) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (!length(x)) return(as.integer(fallback))
  nd <- vapply(x, function(v) {
    for (d in 0:max_d) {
      if (abs(round(v, d) - v) <= 1e-7 * max(1, abs(v)) + 1e-10) return(d)
    }
    max_d
  }, integer(1))
  as.integer(names(sort(table(nd), decreasing = TRUE))[1])
}

decimal_places <- function(x, fallback = 3L) {
  if (is.character(x) || is.factor(x)) {
    d <- decimals_from_text(x)
    if (!is.na(d)) return(d)
  }
  decimals_from_numeric(x, fallback = fallback)
}

infer_raw_decimals <- function(num, txt = NULL) {
  decs <- list()
  nms <- names(num)
  for (i in seq_along(nms)) {
    col <- num[[i]]
    txt_col <- if (!is.null(txt) && i <= ncol(txt)) txt[[i]] else NULL
    d <- NA_integer_
    if (is.numeric(col) || is.logical(col))
      d <- decimals_from_numeric(col)
    if (is.na(d)) d <- decimals_from_text(txt_col)
    if (is.na(d) && !is.numeric(col)) d <- decimals_from_text(col)
    if (!is.na(d)) {
      if (is_isotope_ratio_col(nms[i])) d <- 3L
      decs[[nms[i]]] <- as.integer(min(4L, max(0L, d)))
    }
  }
  decs
}

get_raw_decimals <- function(df = NULL) {
  d <- attr(df, "raw_decimals")
  if (is.list(d) && length(d)) return(d)
  getOption("isotope_app.raw_decimals", default = list())
}

set_raw_decimals <- function(df, decs) {
  if (!is.list(decs)) decs <- list()
  options(isotope_app.raw_decimals = decs)
  if (!is.null(df)) attr(df, "raw_decimals") <- decs
  df
}

is_isotope_ratio_col <- function(nm) {
  grepl("d 13C/12C|d 15N/14N|d 18O/16O|Measured-True|Blank corrected-True", nm) ||
    grepl("(Blank|International|Mass|Drift) corrected d 1", nm)
}

is_true_value_col <- function(nm) {
  grepl("^True d ", nm)
}

# Map a column name to the raw-file precision it must not exceed.
col_raw_digits <- function(df, nm, fallback = 3L) {
  if (is_isotope_ratio_col(nm)) return(3L)
  decs <- get_raw_decimals(df)
  if (is.list(decs) && !is.null(decs[[nm]]))
    return(as.integer(min(4L, max(0L, decs[[nm]]))))
  pick <- function(...) {
    for (k in c(...)) if (!is.null(decs[[k]])) return(as.integer(decs[[k]]))
    NA_integer_
  }
  d <- NA_integer_
  if (grepl("Area All N", nm) || grepl("µg N|mg N", nm)) d <- pick("Area All N")
  else if (grepl("Area All C", nm) || grepl("µg C|mg C", nm)) d <- pick("Area All C")
  else if (grepl("Area All", nm)) d <- pick("Area All")
  if (is.na(d) && nm %in% names(df)) d <- decimal_places(df[[nm]], fallback)
  if (is.na(d)) d <- fallback
  as.integer(min(4L, max(0L, d)))
}

# Isotope ratios are always 3 d.p. (Thermo raw). Other numeric cols follow raw file.
round_like_raw <- function(df, fallback = 3L) {
  if (is.null(df) || !is.data.frame(df) || !nrow(df) || !ncol(df)) return(df)
  skip <- c("Row", "Plot ID", "Peak", "Row number", "Possibly bad sample",
            "outlier", "outlier_C", "outlier_O", "outlier_N")
  for (nm in names(df)) {
    if (nm %in% skip || !is.numeric(df[[nm]])) next
    if (is_true_value_col(nm)) next
    if (is_isotope_ratio_col(nm)) {
      df[[nm]] <- round(df[[nm]], 3L)
      next
    }
    if (!grepl("Area All|µg |mg |Sample weight|Identifier 2|rArea Flash|Amt% Flash|Rt Flash|C/N", nm))
      next
    df[[nm]] <- round(df[[nm]], col_raw_digits(df, nm, fallback))
  }
  attr(df, "raw_decimals") <- get_raw_decimals(df)
  df
}

# Round corrected / Measured-True columns to the same decimals as raw C or O
round_corrected_like_raw <- function(df, raw_c = NULL, raw_o = NULL) {
  round_like_raw(df)
}

read_excel_raw <- function(path, sheet = NULL, skip = 0) {
  ext <- tolower(tools::file_ext(path))
  reader <- if (ext %in% c("xlsx", "xlsm")) readxl::read_xlsx else readxl::read_xls
  args <- list(path = path, skip = skip, .name_repair = "minimal")
  if (!is.null(sheet)) args$sheet <- sheet
  num <- as.data.frame(do.call(reader, args), stringsAsFactors = FALSE)
  txt <- tryCatch({
    a2 <- args
    a2$col_types <- rep("text", max(1L, ncol(num)))
    as.data.frame(do.call(reader, a2), stringsAsFactors = FALSE)
  }, error = function(e) NULL)
  list(num = num, txt = txt)
}

pick_cols <- function(df, cols) {
  for (nm in cols) if (!nm %in% names(df)) df[[nm]] <- NA
  df[, cols, drop = FALSE]
}

plot_theme <- theme_light()

# Black = kept (line fitted on these); red = ticked for removal.
# Labels = sequential Row number (same index as the sidebar checkboxes).
# Equation annotation matches Excel embeds (eq_label).
plot_std_scatter <- function(df, xvar, yvar, title, xlabel, ylabel,
                             exclude = integer(0),
                             slope = NULL, intercept = NULL, r2 = NULL,
                             through_origin = FALSE) {
  df <- as.data.frame(df)
  n <- nrow(df)
  if (is.null(df[["Row number"]])) df[["Row number"]] <- seq_len(n)
  df[["Row number"]] <- as.integer(df[["Row number"]])
  excl <- clean_idx(exclude, n)
  df$.out <- FALSE
  if (length(excl) > 0) df$.out[excl] <- TRUE
  keep <- df[!df$.out, , drop = FALSE]
  rem <- df[df$.out, , drop = FALSE]
  p <- ggplot() + plot_theme + labs(title = title, x = xlabel, y = ylabel)
  if (nrow(keep) > 0) {
    form <- if (isTRUE(through_origin)) y ~ 0 + x else y ~ x
    p <- p +
      geom_point(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]),
                 color = "black", size = 2.2) +
      geom_smooth(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]),
                  method = "lm", se = FALSE, color = "blue", formula = form) +
      geom_text_repel(data = keep,
                      aes(x = .data[[xvar]], y = .data[[yvar]],
                          label = .data[["Row number"]]),
                      color = "black", size = 4, fontface = "bold",
                      max.overlaps = Inf, min.segment.length = 0,
                      box.padding = 0.4, point.padding = 0.3,
                      force = 1.5, seed = 1)
    # Formula: use provided coefs, else fit on kept points (same as Excel)
    if (is.null(slope) || is.null(r2)) {
      ok <- is.finite(keep[[xvar]]) & is.finite(keep[[yvar]])
      if (sum(ok) >= 2L) {
        fit <- tryCatch(
          if (isTRUE(through_origin))
            lm(keep[[yvar]][ok] ~ 0 + keep[[xvar]][ok])
          else
            lm(keep[[yvar]][ok] ~ keep[[xvar]][ok]),
          error = function(e) NULL)
        if (!is.null(fit)) {
          cf <- coef(fit)
          if (isTRUE(through_origin)) {
            slope <- unname(cf[1])
            intercept <- 0
          } else {
            intercept <- unname(cf[1])
            slope <- unname(cf[2])
          }
          r2 <- summary(fit)$r.squared
        }
      }
    }
    if (!is.null(slope) && is.finite(slope) && !is.null(r2) && is.finite(r2)) {
      if (is.null(intercept) || !is.finite(intercept)) intercept <- 0
      xr <- range(keep[[xvar]], na.rm = TRUE)
      yr <- range(keep[[yvar]], na.rm = TRUE)
      if (all(is.finite(xr)) && all(is.finite(yr))) {
        p <- p + annotate("text",
                          x = mean(xr),
                          y = max(yr),
                          label = eq_label(slope, intercept, r2),
                          vjust = -0.6, size = 3.5) +
          coord_cartesian(clip = "off") +
          theme(plot.margin = margin(12, 8, 8, 8))
      }
    }
  }
  if (nrow(rem) > 0) {
    p <- p +
      geom_point(data = rem, aes(x = .data[[xvar]], y = .data[[yvar]]),
                 color = "red", size = 3) +
      geom_text_repel(data = rem,
                      aes(x = .data[[xvar]], y = .data[[yvar]],
                          label = .data[["Row number"]]),
                      color = "red", size = 4, fontface = "bold",
                      max.overlaps = Inf, min.segment.length = 0,
                      box.padding = 0.4, point.padding = 0.3,
                      force = 1.5, seed = 1)
  }
  p
}

style_corr_dt <- function(df, green_cols, red_col = NULL, easy_hscroll = FALSE) {
  df <- round_like_raw(as.data.frame(df))
  opts <- list(
    scrollX = TRUE,
    autoWidth = FALSE,
    pageLength = if (isTRUE(easy_hscroll)) 25 else 50,
    lengthMenu = list(c(25, 50, 100, -1), c("25", "50", "100", "All"))
  )
  if (isTRUE(easy_hscroll)) {
    opts$scrollY <- "60vh"
    opts$scrollCollapse <- TRUE
  }
  dt <- datatable(df, options = opts, rownames = FALSE, class = "display nowrap compact")
  num_cols <- names(df)[vapply(df, is.numeric, logical(1))]
  iso_cols <- num_cols[grepl("d 13C|d 15N|d 18O|Measured-True|True d |Blank corrected-True|(Blank|International|Mass|Drift) corrected d 1", num_cols)]
  tcd_int_cols <- num_cols[grepl("rArea Flash", num_cols)]
  tcd_qty_cols <- num_cols[grepl("µg |mg |C/N|Amt% Flash|Sample weight|Area All", num_cols)]
  rt_cols <- num_cols[grepl("Rt Flash", num_cols)]
  for (col in iso_cols) {
    dt <- formatRound(dt, columns = col, digits = 3, mark = "")
  }
  for (col in tcd_int_cols) {
    dt <- formatRound(dt, columns = col, digits = 0, mark = ",", interval = 3)
  }
  for (col in tcd_qty_cols) {
    dt <- formatRound(dt, columns = col, digits = col_raw_digits(df, col), mark = ",", interval = 3)
  }
  for (col in rt_cols) {
    dt <- formatRound(dt, columns = col, digits = 0, mark = "")
  }
  for (col in intersect(green_cols, names(df))) {
    dt <- formatStyle(dt, col, backgroundColor = "#C6EFCE")
  }
  if (!is.null(red_col) && red_col %in% names(df)) {
    dt <- formatStyle(dt, red_col, target = "row",
                      backgroundColor = styleEqual(c(1, "1"), "#FFC7CE"))
  }
  dt
}

int_to_col_ref <- function(n) {
  out <- ""
  while (n > 0) {
    r <- (n - 1) %% 26
    out <- paste0(LETTERS[r + 1], out)
    n <- (n - r - 1) %/% 26
  }
  out
}

eq_label <- function(slope, intercept, r2, digits = 5) {
  paste0("y = ", round(slope, digits), " x + ", round(intercept, digits),
         "  R-squared=", round(r2, digits))
}

# Workbook scatter: black kept / optional red excluded, Plot ID labels, optional equation
plot_wb_scatter <- function(df, xvar, yvar, title, xlabel, ylabel,
                            slope = NULL, intercept = NULL, r2 = NULL,
                            excl_flag = "outlier", include_outliers = TRUE) {
  df <- as.data.frame(df)
  if (is.null(df[["Plot ID"]])) {
    df[["Plot ID"]] <- if (!is.null(df[["Row number"]])) df[["Row number"]] else seq_len(nrow(df))
  }
  keep <- if (excl_flag %in% names(df)) df[df[[excl_flag]] != "Yes", , drop = FALSE] else df
  rem  <- if (include_outliers && excl_flag %in% names(df))
    df[df[[excl_flag]] == "Yes", , drop = FALSE] else df[0, ]
  p <- ggplot() + plot_theme + labs(title = title, x = xlabel, y = ylabel)
  if (nrow(keep) > 0) {
    p <- p +
      geom_point(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]), color = "black") +
      geom_smooth(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]),
                  method = "lm", se = FALSE, color = "blue", formula = y ~ x) +
      geom_text_repel(data = keep,
                      aes(x = .data[[xvar]], y = .data[[yvar]],
                          label = .data[["Plot ID"]]),
                      color = "black", size = 3.5, fontface = "bold",
                      max.overlaps = Inf, min.segment.length = 0,
                      box.padding = 0.35, point.padding = 0.25, seed = 1)
  }
  if (nrow(rem) > 0) {
    p <- p +
      geom_point(data = rem, aes(x = .data[[xvar]], y = .data[[yvar]]),
                 color = "red", size = 2.5) +
      geom_text_repel(data = rem,
                      aes(x = .data[[xvar]], y = .data[[yvar]],
                          label = .data[["Plot ID"]]),
                      color = "red", size = 3.5, fontface = "bold",
                      max.overlaps = Inf, min.segment.length = 0,
                      box.padding = 0.35, point.padding = 0.25, seed = 1)
  }
  if (!is.null(slope) && nrow(keep) > 0) {
    xr <- range(keep[[xvar]], na.rm = TRUE)
    yr <- range(keep[[yvar]], na.rm = TRUE)
    p <- p + annotate("text",
                      x = mean(xr), y = max(yr, na.rm = TRUE),
                      label = eq_label(slope, intercept, r2),
                      vjust = -0.6, size = 3)
  }
  p
}

calculate_col_widths <- function(df) {
  if (is.null(df) || ncol(df) == 0) return(numeric(0))
  data_widths <- vapply(df, function(col) {
    w <- nchar(as.character(col))
    w <- w[is.finite(w)]
    if (length(w) == 0) 0L else max(w)
  }, integer(1))
  name_widths <- nchar(names(df))
  pmax(8, pmin(45, pmax(data_widths, name_widths + 3)))
}

# Save ggplot PNGs and insert; keep temp paths until saveWorkbook copies them
if (!exists(".embed_tmp_env", inherits = TRUE)) {
  .embed_tmp_env <- new.env(parent = emptyenv())
  .embed_tmp_env$files <- character(0)
}

embed_ggplot <- function(wb, sheet, plot, startRow, startCol,
                         width = 6, height = 4, dpi = 150) {
  tryCatch({
    tf <- tempfile(fileext = ".png")
    ggsave(tf, plot, width = width, height = height, dpi = dpi, limitsize = FALSE)
    .embed_tmp_env$files <- c(.embed_tmp_env$files, tf)
    insertImage(wb, sheet, tf, startRow = startRow, startCol = startCol,
                width = width, height = height, units = "in")
  }, error = function(e) {
    warning("Could not embed plot on sheet ", sheet, ": ", conditionMessage(e),
            call. = FALSE)
    invisible(NULL)
  })
}

clear_embed_tmp <- function() {
