# Base64 without extra packages (jsonlite may be missing under webR).
raw_to_base64 <- function(bytes) {
  if (!length(bytes)) return("")
  chars <- c(LETTERS, letters, as.character(0:9), "+", "/")
  n <- length(bytes)
  pad <- (3L - n %% 3L) %% 3L
  if (pad) bytes <- c(bytes, raw(pad))
  b1 <- as.integer(bytes[seq.int(1L, length(bytes), 3L)])
  b2 <- as.integer(bytes[seq.int(2L, length(bytes), 3L)])
  b3 <- as.integer(bytes[seq.int(3L, length(bytes), 3L)])
  n24 <- b1 * 65536L + b2 * 256L + b3
  ch <- chars[c(rbind(
    n24 %/% 262144L %% 64L + 1L,
    n24 %/% 4096L %% 64L + 1L,
    n24 %/% 64L %% 64L + 1L,
    n24 %% 64L + 1L
  ))]
  s <- paste(ch, collapse = "")
  if (pad == 1L) substr(s, nchar(s), nchar(s)) <- "="
  if (pad == 2L) substr(s, nchar(s) - 1L, nchar(s)) <- "=="
  s
}

file_to_base64 <- function(path) {
  n <- file.info(path)$size
  if (is.na(n) || n < 1) stop("Excel file is empty.")
  raw_to_base64(readBin(path, what = "raw", n = n))
}

