# Drop raw amp/area cols; match example corrected sheet layout
format_export_dfs <- function(res, std_values) {
  idf <- res$International_df
  mdf <- res$Mass_df
  sdf <- res$Sample_df
  if (!is.null(idf) && nrow(idf) > 0) {
    if (!"Comment" %in% names(idf) && "Identifier 2" %in% names(idf))
      idf[["Comment"]] <- idf[["Identifier 2"]]
    if (!is.null(idf[["True d 13C/12C"]])) {
      idf[["Measured-TrueC"]] <- idf[["d 13C/12C"]] - idf[["True d 13C/12C"]]
      idf[["Measured-TrueO"]] <- idf[["d 18O/16O(SMOW)"]] - idf[["True d 18O/16O(SMOW)"]]
    }
    idf[["Plot ID"]] <- if (!is.null(idf[["Row number"]])) idf[["Row number"]] else seq_len(nrow(idf))
    idf <- finalize_std_export(idf, intl_corrected_cols)
    idf <- pick_cols(idf, export_intl_cols)
  }
  if (!is.null(mdf) && nrow(mdf) > 0) {
    if (!"Comment" %in% names(mdf) && "Identifier 2" %in% names(mdf))
      mdf[["Comment"]] <- mdf[["Identifier 2"]]
    mdf[["True d 13C/12C"]] <- std_values$STDC
    mdf[["True d 18O/16O(SMOW)"]] <- std_values$STDO
    mdf[["Measured-TrueC"]] <- mdf[["d 13C/12C"]] - std_values$STDC
    mdf[["Measured-TrueO"]] <- mdf[["d 18O/16O(SMOW)"]] - std_values$STDO
    mdf[["Plot ID"]] <- if (!is.null(mdf[["Row number"]])) mdf[["Row number"]] else seq_len(nrow(mdf))
    mdf <- finalize_std_export(mdf, mass_corrected_cols)
    mdf <- pick_cols(mdf, export_mass_cols)
  }
  if (!is.null(sdf) && nrow(sdf) > 0) {
    sdf <- pick_cols(sdf, export_sample_cols)
  }
  list(Sample_df = sdf, International_df = idf, Mass_df = mdf)
}

# ---------- verified correction pipeline ----------
apply_corrections_v2 <- function(International_df, Mass_df, Sample_df,
                                 std_values, exclude_intl = integer(0),
                                 exclude_mass = integer(0),
                                 exclude_intl_c = NULL, exclude_intl_o = NULL,
                                 exclude_mass_c = NULL, exclude_mass_o = NULL,
                                 outlier = integer(0), outlier2 = integer(0),
                                 outlier3 = integer(0)) {
  STDC <- std_values$STDC; STDO <- std_values$STDO
  results <- list()
  International_df <- attach_true_intl(International_df, std_values)
  International_df[["Measured-TrueC"]] <-
    International_df[["d 13C/12C"]] - International_df[["True d 13C/12C"]]
  International_df[["Measured-TrueO"]] <-
    International_df[["d 18O/16O(SMOW)"]] - International_df[["True d 18O/16O(SMOW)"]]
  International_df[["Row number"]] <- seq_len(nrow(International_df))
  International_df <- stamp_dual_outliers(
    International_df,
    resolve_excl(exclude_intl_c, exclude_intl),
    resolve_excl(exclude_intl_o, exclude_intl),
    "outlier_C", "outlier_O")
  fit_int_c <- International_df[International_df$outlier_C != "Yes", , drop = FALSE]
  fit_int_o <- International_df[International_df$outlier_O != "Yes", , drop = FALSE]
  keep_c <- which(!is.na(fit_int_c[["True d 13C/12C"]]))
  keep_o <- which(!is.na(fit_int_o[["True d 18O/16O(SMOW)"]]))
  if (length(keep_c) >= 2 && length(keep_o) >= 2) {
    mC <- lm(fit_int_c[["True d 13C/12C"]][keep_c] ~ fit_int_c[["d 13C/12C"]][keep_c])
    mO <- lm(fit_int_o[["True d 18O/16O(SMOW)"]][keep_o] ~ fit_int_o[["d 18O/16O(SMOW)"]][keep_o])
    results$C_slope <- unname(coef(mC)[2]); results$C_intercept <- unname(coef(mC)[1])
    results$O_slope <- unname(coef(mO)[2]); results$O_intercept <- unname(coef(mO)[1])
    results$C_r2 <- summary(mC)$r.squared
    results$O_r2 <- summary(mO)$r.squared
    International_df[["International corrected d 13C/12C"]] <-
      International_df[["d 13C/12C"]] * results$C_slope + results$C_intercept
    International_df[["International corrected d 18O/16O(SMOW)"]] <-
      International_df[["d 18O/16O(SMOW)"]] * results$O_slope + results$O_intercept
    # Rmd uses raw measured SMOW for the intl PDB column (not intl-corrected SMOW)
    International_df[["International corrected d 18O/16O(PDB)"]] <-
      (International_df[["d 18O/16O(SMOW)"]] - 30.86) / 1.03086
  } else if (length(keep_c) >= 2) {
    mC <- lm(fit_int_c[["True d 13C/12C"]][keep_c] ~ fit_int_c[["d 13C/12C"]][keep_c])
    results$C_slope <- unname(coef(mC)[2]); results$C_intercept <- unname(coef(mC)[1])
    results$C_r2 <- summary(mC)$r.squared
    International_df[["International corrected d 13C/12C"]] <-
      International_df[["d 13C/12C"]] * results$C_slope + results$C_intercept
  } else if (length(keep_o) >= 2) {
    mO <- lm(fit_int_o[["True d 18O/16O(SMOW)"]][keep_o] ~ fit_int_o[["d 18O/16O(SMOW)"]][keep_o])
    results$O_slope <- unname(coef(mO)[2]); results$O_intercept <- unname(coef(mO)[1])
    results$O_r2 <- summary(mO)$r.squared
    International_df[["International corrected d 18O/16O(SMOW)"]] <-
      International_df[["d 18O/16O(SMOW)"]] * results$O_slope + results$O_intercept
    International_df[["International corrected d 18O/16O(PDB)"]] <-
      (International_df[["d 18O/16O(SMOW)"]] - 30.86) / 1.03086
  }
  results$International_df <- International_df
  Mass_df[["Row number"]] <- seq_len(nrow(Mass_df))
  Mass_df[["True d 13C/12C"]] <- STDC
  Mass_df[["True d 18O/16O(SMOW)"]] <- STDO
  Mass_df[["Measured-TrueC"]] <- Mass_df[["d 13C/12C"]] - STDC
  Mass_df[["Measured-TrueO"]] <- Mass_df[["d 18O/16O(SMOW)"]] - STDO
  Mass_df <- stamp_dual_outliers(
    Mass_df,
    resolve_excl(exclude_mass_c, exclude_mass),
    resolve_excl(exclude_mass_o, exclude_mass),
    "outlier_C", "outlier_O")
  if (nrow(Mass_df) > 1 && !is.null(results$C_slope) && !is.null(results$O_slope)) {
    Mass_df[["International corrected d 13C/12C"]] <-
      Mass_df[["d 13C/12C"]] * results$C_slope + results$C_intercept
    Mass_df[["International corrected d 18O/16O(SMOW)"]] <-
      Mass_df[["d 18O/16O(SMOW)"]] * results$O_slope + results$O_intercept
    mass_fit_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    mass_fit_o <- Mass_df[Mass_df$outlier_O != "Yes", , drop = FALSE]
    mMC <- lm(mass_fit_c[["International corrected d 13C/12C"]] ~ mass_fit_c[["Area All"]])
    mMO <- lm(mass_fit_o[["International corrected d 18O/16O(SMOW)"]] ~ mass_fit_o[["Area All"]])
    results$Mass_C_slope <- unname(coef(mMC)[2]); results$Mass_C_intercept <- unname(coef(mMC)[1])
    results$Mass_O_slope <- unname(coef(mMO)[2]); results$Mass_O_intercept <- unname(coef(mMO)[1])
    results$Mass_C_r2 <- summary(mMC)$r.squared
    results$Mass_O_r2 <- summary(mMO)$r.squared
    # Rmd / example workbooks center mass correction on sample Area All
    # (not the inhouse mean). Fall back to inhouse mean if no samples.
    if (nrow(Sample_df) > 0) {
      samp_area <- Sample_df[["Area All"]]
      id1 <- toupper(as.character(Sample_df[["Identifier 1"]]))
      area_ref <- mean(samp_area[id1 != "BLANK"], na.rm = TRUE)
      if (!is.finite(area_ref)) area_ref <- mean(samp_area, na.rm = TRUE)
    } else {
      area_ref <- mean(mass_fit_c[["Area All"]], na.rm = TRUE)
    }
    results$area_ref <- area_ref
    Mass_df[["Mass corrected d 13C/12C"]] <-
      Mass_df[["International corrected d 13C/12C"]] -
      (Mass_df[["Area All"]] - area_ref) * results$Mass_C_slope
    Mass_df[["Mass corrected d 18O/16O(SMOW)"]] <-
      Mass_df[["International corrected d 18O/16O(SMOW)"]] -
      (Mass_df[["Area All"]] - area_ref) * results$Mass_O_slope
    mass_fit_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    mass_fit_o <- Mass_df[Mass_df$outlier_O != "Yes", , drop = FALSE]
    mDC <- lm(mass_fit_c[["Mass corrected d 13C/12C"]] ~ mass_fit_c$Row)
    mDO <- lm(mass_fit_o[["Mass corrected d 18O/16O(SMOW)"]] ~ mass_fit_o$Row)
    results$Drift_C_slope <- unname(coef(mDC)[2]); results$Drift_C_intercept <- unname(coef(mDC)[1])
    results$Drift_O_slope <- unname(coef(mDO)[2]); results$Drift_O_intercept <- unname(coef(mDO)[1])
    results$Drift_C_r2 <- summary(mDC)$r.squared
    results$Drift_O_r2 <- summary(mDO)$r.squared
    Mass_df[["Drift corrected d 13C/12C"]] <-
      Mass_df[["Mass corrected d 13C/12C"]] -
      (Mass_df$Row * results$Drift_C_slope + results$Drift_C_intercept - STDC)
    Mass_df[["Drift corrected d 18O/16O(SMOW)"]] <-
      Mass_df[["Mass corrected d 18O/16O(SMOW)"]] -
      (Mass_df$Row * results$Drift_O_slope + results$Drift_O_intercept - STDO)
    Mass_df[["Drift corrected d 18O/16O(PDB)"]] <-
      (Mass_df[["Drift corrected d 18O/16O(SMOW)"]] - 30.86) / 1.03086
    if (nrow(Sample_df) > 0) {
      Sample_df[["International corrected d 13C/12C"]] <-
        Sample_df[["d 13C/12C"]] * results$C_slope + results$C_intercept
      Sample_df[["International corrected d 18O/16O(SMOW)"]] <-
        Sample_df[["d 18O/16O(SMOW)"]] * results$O_slope + results$O_intercept
      Sample_df[["Mass corrected d 13C/12C"]] <-
        Sample_df[["International corrected d 13C/12C"]] -
        (Sample_df[["Area All"]] - area_ref) * results$Mass_C_slope
      Sample_df[["Mass corrected d 18O/16O(SMOW)"]] <-
        Sample_df[["International corrected d 18O/16O(SMOW)"]] -
        (Sample_df[["Area All"]] - area_ref) * results$Mass_O_slope
      Sample_df[["Drift corrected d 13C/12C"]] <-
        Sample_df[["Mass corrected d 13C/12C"]] -
        (Sample_df$Row * results$Drift_C_slope + results$Drift_C_intercept - STDC)
      Sample_df[["Drift corrected d 18O/16O(SMOW)"]] <-
        Sample_df[["Mass corrected d 18O/16O(SMOW)"]] -
        (Sample_df$Row * results$Drift_O_slope + results$Drift_O_intercept - STDO)
      Sample_df[["Drift corrected d 18O/16O(PDB)"]] <-
        (Sample_df[["Drift corrected d 18O/16O(SMOW)"]] - 30.86) / 1.03086
      Sample_df[["Comment"]] <- Sample_df[["Identifier 2"]]
      Sample_df <- annotate_sample_qa(Sample_df, outlier, outlier2, outlier3)
    }
  }
  # Round after all fits so coefficients stay full precision
  International_df <- round_corrected_like_raw(International_df)
  Mass_df <- round_corrected_like_raw(Mass_df)
  Sample_df <- round_corrected_like_raw(Sample_df)
  results$International_df <- International_df
  results$Mass_df <- Mass_df
  results$Sample_df <- Sample_df
  results
}

