}

build_workbook <- function(res, std_values, coef_df) {
  clear_embed_tmp()
  exp <- format_export_dfs(res, std_values)
  Sample_df <- exp$Sample_df
  International_df <- exp$International_df
  Mass_df <- exp$Mass_df

  wb <- createWorkbook()
  hs <- createStyle(fontSize = 11, fontColour = "#000000", fgFill = "grey", textDecoration = "bold")
  highlight  <- createStyle(fontColour = "#000000", bgFill = "green")
  highlight2 <- createStyle(fontColour = "#000000", bgFill = "red")

  addSheet <- function(name, dat) {
    addWorksheet(wb, name, tabColour = unname(sheet_tab_colours[[name]]))
    writeData(wb, name, dat, headerStyle = hs, withFilter = TRUE)
    if (!is.null(dat) && ncol(dat) > 0)
      setColWidths(wb, name, cols = seq_len(ncol(dat)), widths = calculate_col_widths(dat))
  }

  addSheet("Samples", Sample_df)
  addSheet("International_standards", International_df)
  addSheet("Inhouse_standards", Mass_df)
  addSheet("Coefficients", coef_df)

  cf_green <- function(sheet, dat, col_names) {
    n <- nrow(dat)
    if (n == 0) return(NULL)
    for (j in which(names(dat) %in% col_names)) {
      colref <- int_to_col_ref(j)
      conditionalFormatting(wb, sheet, cols = j, rows = 2:(n + 1),
        rule = paste0("ISNUMBER($", colref, "2)"), style = highlight)
    }
  }
  cf_red <- function(sheet, dat, flag_col) {
    n <- nrow(dat)
    j <- match(flag_col, names(dat))
    if (n == 0 || is.na(j)) return(NULL)
    conditionalFormatting(wb, sheet, cols = 1:ncol(dat), rows = 2:(n + 1),
      rule = paste0("$", int_to_col_ref(j), "2>0"), style = highlight2)
  }
  cf_green("Samples", Sample_df, c(
    "Drift corrected d 13C/12C",
    "Drift corrected d 18O/16O(SMOW)",
    "Drift corrected d 18O/16O(PDB)"))
  cf_red("Samples", Sample_df, "Possibly bad sample")
  cf_green("International_standards", International_df, c(
    "International corrected d 13C/12C",
    "International corrected d 18O/16O(SMOW)",
    "International corrected d 18O/16O(PDB)"))
  cf_green("Inhouse_standards", Mass_df, c(
    "Drift corrected d 13C/12C",
    "Drift corrected d 18O/16O(SMOW)",
    "Drift corrected d 18O/16O(PDB)"))

  # ---- embed plots (same sheet positions as the Rmd) ----
  idf <- res$International_df
  mdf <- res$Mass_df
  if (!is.null(idf) && length(unique(idf[["Identifier 1"]])) > 1 &&
      !is.null(res$C_slope)) {
    embed_ggplot(wb, "International_standards",
      plot_wb_scatter(idf, "d 13C/12C", "True d 13C/12C",
        "International correction - Carbon", "Measured d13C", "True d13C",
        res$C_slope, res$C_intercept, res$C_r2, excl_flag = "outlier_C"),
      startRow = 20, startCol = 7)
    embed_ggplot(wb, "International_standards",
      plot_wb_scatter(idf, "d 18O/16O(SMOW)", "True d 18O/16O(SMOW)",
        "International correction - Oxygen", "Measured d18O", "True d18O",
        res$O_slope, res$O_intercept, res$O_r2, excl_flag = "outlier_O"),
      startRow = 20, startCol = 14)
    keep_i_c <- idf[idf$outlier_C != "Yes", , drop = FALSE]
    keep_i_o <- idf[idf$outlier_O != "Yes", , drop = FALSE]
    if (nrow(keep_i_c) > 1 && nrow(keep_i_o) > 1) {
      mC2 <- lm(keep_i_c[["True d 13C/12C"]] ~ keep_i_c[["International corrected d 13C/12C"]])
      mO2 <- lm(keep_i_o[["True d 18O/16O(SMOW)"]] ~ keep_i_o[["International corrected d 18O/16O(SMOW)"]])
      embed_ggplot(wb, "International_standards",
        plot_wb_scatter(keep_i_c, "International corrected d 13C/12C", "True d 13C/12C",
          "International check - Carbon", "Intl corr d13C", "True d13C",
          unname(coef(mC2)[2]), unname(coef(mC2)[1]), summary(mC2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 7)
      embed_ggplot(wb, "International_standards",
        plot_wb_scatter(keep_i_o, "International corrected d 18O/16O(SMOW)", "True d 18O/16O(SMOW)",
          "International check - Oxygen", "Intl corr d18O", "True d18O",
          unname(coef(mO2)[2]), unname(coef(mO2)[1]), summary(mO2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 14)
    }
  }
  if (!is.null(mdf) && nrow(mdf) > 1 && !is.null(res$Mass_C_slope)) {
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Area All", "International corrected d 13C/12C",
        "Mass correction - Carbon", "Area All", "Intl corr d13C",
        res$Mass_C_slope, res$Mass_C_intercept, res$Mass_C_r2, excl_flag = "outlier_C"),
      startRow = 20, startCol = 7)
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Area All", "International corrected d 18O/16O(SMOW)",
        "Mass correction - Oxygen", "Area All", "Intl corr d18O",
        res$Mass_O_slope, res$Mass_O_intercept, res$Mass_O_r2, excl_flag = "outlier_O"),
      startRow = 20, startCol = 14)
    keep_m_c <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
    keep_m_o <- mdf[mdf$outlier_O != "Yes", , drop = FALSE]
    if (nrow(keep_m_c) > 1 && nrow(keep_m_o) > 1) {
      mMC2 <- lm(keep_m_c[["Mass corrected d 13C/12C"]] ~ keep_m_c[["Area All"]])
      mMO2 <- lm(keep_m_o[["Mass corrected d 18O/16O(SMOW)"]] ~ keep_m_o[["Area All"]])
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Area All", "Mass corrected d 13C/12C",
          "Mass check - Carbon", "Area All", "Mass corr d13C",
          unname(coef(mMC2)[2]), unname(coef(mMC2)[1]), summary(mMC2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 7)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_o, "Area All", "Mass corrected d 18O/16O(SMOW)",
          "Mass check - Oxygen", "Area All", "Mass corr d18O",
          unname(coef(mMO2)[2]), unname(coef(mMO2)[1]), summary(mMO2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 14)
    }
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Row", "Mass corrected d 13C/12C",
        "Drift correction - Carbon", "Row", "Mass corr d13C",
        res$Drift_C_slope, res$Drift_C_intercept, res$Drift_C_r2, excl_flag = "outlier_C"),
      startRow = 61, startCol = 7)
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Row", "Mass corrected d 18O/16O(SMOW)",
        "Drift correction - Oxygen", "Row", "Mass corr d18O",
        res$Drift_O_slope, res$Drift_O_intercept, res$Drift_O_r2, excl_flag = "outlier_O"),
      startRow = 61, startCol = 14)
    if (nrow(keep_m_c) > 1 && nrow(keep_m_o) > 1 && "Drift corrected d 13C/12C" %in% names(mdf)) {
      mDC2 <- lm(keep_m_c[["Drift corrected d 13C/12C"]] ~ keep_m_c$Row)
      mDO2 <- lm(keep_m_o[["Drift corrected d 18O/16O(SMOW)"]] ~ keep_m_o$Row)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Row", "Drift corrected d 13C/12C",
          "Drift check - Carbon", "Row", "Drift corr d13C",
          unname(coef(mDC2)[2]), unname(coef(mDC2)[1]), summary(mDC2)$r.squared,
          include_outliers = FALSE),
        startRow = 81, startCol = 7)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_o, "Row", "Drift corrected d 18O/16O(SMOW)",
          "Drift check - Oxygen", "Row", "Drift corr d18O",
          unname(coef(mDO2)[2]), unname(coef(mDO2)[1]), summary(mDO2)$r.squared,
          include_outliers = FALSE),
        startRow = 81, startCol = 14)
    }
  }

  wb
}

