          tabPanel("Inhouse standards", value = "inhouse",
                   br(), p("Row names are Identifier 1. Plot numbers match the ticks at left. Correction plots keep ticked points in red; check plots drop them."),
                   tags$div(`data-guide` = "inhouse-review",
                     DTOutput(ns("mass_named_table")),
                     br(),
                     h4("Mass then drift correction"),
                     fluidRow(
                       column(6, plotOutput(ns("q_mass_c"), height = "380px")),
                       column(6, plotOutput(ns("q_mass_o"), height = "380px"))),
                     fluidRow(
                       column(6, plotOutput(ns("q_drift_c"), height = "380px")),
                       column(6, plotOutput(ns("q_drift_o"), height = "380px")))),
                   tags$div(`data-guide` = "drift-check",
                     h4("Mass / drift check (outliers removed)"),
                     fluidRow(
                       column(6, plotOutput(ns("q_mass_check_c"), height = "380px")),
                       column(6, plotOutput(ns("q_mass_check_o"), height = "380px"))),
                     fluidRow(
                       column(6, plotOutput(ns("q_drift_check_c"), height = "380px")),
                       column(6, plotOutput(ns("q_drift_check_o"), height = "380px"))))),
          tabPanel("Samples", value = "samples",
                   br(), p("Corrected sample values after Apply. Green columns are the final drift-corrected C and O."),
                   tags$div(`data-guide` = "samples-table",
                     DTOutput(ns("sample_table")))),
          tabPanel("Coefficients", value = "coefficients",
                   br(), tableOutput(ns("coef_table")))
        )
      )
    )
  )
}

# ==================================================================
# Server
# ==================================================================
thermo_gb_server <- function(id) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns
  msg_notran <- "Upload a raw file first."

  observeEvent(input$file, {
    updateTabsetPanel(session, "main_tabs", selected = "international")
  })

  raw_data <- reactive({
    validate(need(input$file, "Upload a raw .xls file first."))
    load_and_fix_peaks(input$file$datapath)
  })

  split_data <- reactive({
    rd <- raw_data()
    format_data(rd$df_subset)
  })
# ----- TAB 1: international standards sorted table -----
  intl_full <- reactive({
    idf <- split_data()$International_df
    if (nrow(idf) == 0) return(idf)
    idf <- attach_true_intl(idf, get_std_values())
    idf[["Measured-TrueO"]] <- round(idf[["d 18O/16O(SMOW)"]] - idf[["True d 18O/16O(SMOW)"]], 3)
    idf[["Measured-TrueC"]] <- round(idf[["d 13C/12C"]] - idf[["True d 13C/12C"]], 3)
    idf[["Row number"]] <- seq_len(nrow(idf))
    idf[["Plot ID"]] <- idf[["Row number"]]
    idf
  })
  intl_sorted <- reactive({
    idf <- intl_full()
    if (nrow(idf) == 0) return(idf)
    intl5_cols <- c("Plot ID", "Row", "Identifier 1", "Area All", "d 13C/12C", "True d 13C/12C",
                    "Measured-TrueC", "d 18O/16O(SMOW)", "True d 18O/16O(SMOW)", "Measured-TrueO")
    idf <- idf[order(idf[["Identifier 1"]], idf$Row), , drop = FALSE]
    idf[, intersect(intl5_cols, names(idf)), drop = FALSE]
  })
  output$intl_sorted_table <- renderDT({
    validate(need(nrow(intl_sorted()) > 0, "No international standards in this file."))
    style_corr_dt(intl_sorted(), c("Measured-TrueC", "Measured-TrueO"))
  })

  output$p_intl_c <- renderPlot({
    res <- preview()
    idf <- res$International_df
    validate(need(!is.null(idf) && nrow(idf) > 1, "No international standards in this file."))
    plot_std_scatter(idf, "d 13C/12C", "True d 13C/12C",
      "International - Carbon", "Measured d13C", "True d13C",
      exclude = pick_excl(input$split_outliers, input$intl_excl, input$intl_excl_c),
      slope = res$C_slope, intercept = res$C_intercept, r2 = res$C_r2)
  })
  output$p_intl_o <- renderPlot({
    res <- preview()
    idf <- res$International_df
    validate(need(!is.null(idf) && nrow(idf) > 1, "No international standards in this file."))
    plot_std_scatter(idf, "d 18O/16O(SMOW)", "True d 18O/16O(SMOW)",
      "International - Oxygen", "Measured d18O", "True d18O",
      exclude = pick_excl(input$split_outliers, input$intl_excl, input$intl_excl_o),
      slope = res$O_slope, intercept = res$O_intercept, r2 = res$O_r2)
  })
  output$p_intl_check_c <- renderPlot({
    res <- preview()
    idf <- res$International_df
    validate(need(!is.null(idf) && nrow(idf) > 1, "No international standards in this file."))
    validate(need("International corrected d 13C/12C" %in% names(idf),
                  "Need enough standards to fit the correction."))
    keep <- idf[idf$outlier_C != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough standards left after removals."))
    plot_std_scatter(keep, "International corrected d 13C/12C", "True d 13C/12C",
      "International check - Carbon", "Intl corr d13C", "True d13C")
  })
  output$p_intl_check_o <- renderPlot({
    res <- preview()
    idf <- res$International_df
    validate(need(!is.null(idf) && nrow(idf) > 1, "No international standards in this file."))
    validate(need("International corrected d 18O/16O(SMOW)" %in% names(idf),
                  "Need enough standards to fit the correction."))
    keep <- idf[idf$outlier_O != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough standards left after removals."))
    plot_std_scatter(keep, "International corrected d 18O/16O(SMOW)", "True d 18O/16O(SMOW)",
      "International check - Oxygen", "Intl corr d18O", "True d18O")
  })

  # ----- Inhouse table: Identifier 1 as the row name -----
  mass_named <- reactive({
    mdf <- split_data()$Mass_df
    if (nrow(mdf) == 0) return(mdf)
    sv <- get_std_values()
    mdf[["Row number"]] <- seq_len(nrow(mdf))
    mdf[["Plot ID"]] <- mdf[["Row number"]]
    mdf[["True d 13C/12C"]] <- sv$STDC
    mdf[["True d 18O/16O(SMOW)"]] <- sv$STDO
    mdf[["Measured-TrueC"]] <- round(mdf[["d 13C/12C"]] - sv$STDC, 3)
    mdf[["Measured-TrueO"]] <- round(mdf[["d 18O/16O(SMOW)"]] - sv$STDO, 3)
    cols <- c("Plot ID", "Row", "Identifier 1", "Area All",
              "d 13C/12C", "True d 13C/12C", "Measured-TrueC",
              "d 18O/16O(SMOW)", "True d 18O/16O(SMOW)", "Measured-TrueO")
    mdf[, intersect(cols, names(mdf)), drop = FALSE]
  })
  output$mass_named_table <- renderDT({
    mdf <- mass_named()
    validate(need(nrow(mdf) > 0, "No inhouse standards in this file."))
    rn <- as.character(mdf[["Identifier 1"]])
    show <- round_like_raw(mdf[, setdiff(names(mdf), "Identifier 1"), drop = FALSE])
    dt <- datatable(show, rownames = rn, options = list(
      scrollX = TRUE,
      pageLength = 50,
      lengthMenu = list(c(25, 50, 100, -1), c("25", "50", "100", "All"))
    ), class = "display nowrap compact")
    iso_m <- names(show)[grepl("d 13C|d 15N|d 18O|Measured-True|True d ", names(show))]
    iso_m <- iso_m[vapply(show[iso_m], is.numeric, logical(1))]
    for (col in iso_m) dt <- formatRound(dt, columns = col, digits = 3, mark = "")
    for (col in intersect(c("Measured-TrueC", "Measured-TrueO"), names(show))) {
      dt <- formatStyle(dt, col, backgroundColor = "#C6EFCE")
    }
    dt
  })

# ----- outlier exclusion checkboxes (combined or C/O split) -----
  output$intl_checks <- renderUI({
    sdf <- split_data()
    idf <- sdf$International_df
    validate(need(nrow(idf) > 0, "No international standards in this file."))
    ids <- if (!is.null(idf[["Identifier 1"]])) idf[["Identifier 1"]] else rep("", nrow(idf))
    if (isTRUE(input$split_outliers)) {
      outlier_dual_checks_ui(ns, "intl_excl_c", "intl_excl_o",
                             "Intl C", "Intl O", nrow(idf), ids)
    } else {
      outlier_single_checks_ui(ns, "intl_excl", "Intl", nrow(idf), ids)
    }
  })

  output$mass_checks <- renderUI({
    sdf <- split_data()
    mdf <- sdf$Mass_df
    validate(need(nrow(mdf) > 0, "No inhouse standards in this file."))
    ids <- if (!is.null(mdf[["Identifier 1"]])) mdf[["Identifier 1"]] else rep("", nrow(mdf))
    if (isTRUE(input$split_outliers)) {
      outlier_dual_checks_ui(ns, "mass_excl_c", "mass_excl_o",
                             "Inhouse C", "Inhouse O", nrow(mdf), ids)
    } else {
      outlier_single_checks_ui(ns, "mass_excl", "Inhouse", nrow(mdf), ids)
    }
  })

# ----- corrected pipeline (runs live with the preview) -----
  get_std_values <- reactive({
    default_std_values
  })

  preview <- reactive({
    sd <- split_data()
    rd <- raw_data()
    split <- isTRUE(input$split_outliers)
    apply_corrections_v2(sd$International_df, sd$Mass_df, sd$Sample_df,
                         get_std_values(),
                         exclude_intl_c = pick_excl(split, input$intl_excl, input$intl_excl_c),
                         exclude_intl_o = pick_excl(split, input$intl_excl, input$intl_excl_o),
                         exclude_mass_c = pick_excl(split, input$mass_excl, input$mass_excl_c),
                         exclude_mass_o = pick_excl(split, input$mass_excl, input$mass_excl_o),
                         outlier = rd$outlier, outlier2 = rd$outlier2,
                         outlier3 = rd$outlier3)
  })

  corrected <- preview

  output$q_mass_c  <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("International corrected d 13C/12C" %in% names(mdf),
                  "Need international standards to fit the correction."))
    plot_std_scatter(mdf, "Area All", "International corrected d 13C/12C",
      "Mass correction - Carbon", "Area All", "Intl corr d13C",
      exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c),
      slope = res$Mass_C_slope, intercept = res$Mass_C_intercept, r2 = res$Mass_C_r2)
  })
  output$q_mass_o  <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("International corrected d 18O/16O(SMOW)" %in% names(mdf),
                  "Need international standards to fit the correction."))
    plot_std_scatter(mdf, "Area All", "International corrected d 18O/16O(SMOW)",
      "Mass correction - Oxygen", "Area All", "Intl corr d18O",
      exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_o),
      slope = res$Mass_O_slope, intercept = res$Mass_O_intercept, r2 = res$Mass_O_r2)
  })
  output$q_drift_c <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Mass corrected d 13C/12C" %in% names(mdf),
                  "Need international standards to fit the correction."))
    plot_std_scatter(mdf, "Row", "Mass corrected d 13C/12C",
      "Drift correction - Carbon", "Row", "Mass corr d13C",
      exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c),
      slope = res$Drift_C_slope, intercept = res$Drift_C_intercept, r2 = res$Drift_C_r2)
  })
  output$q_drift_o <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Mass corrected d 18O/16O(SMOW)" %in% names(mdf),
                  "Need international standards to fit the correction."))
    plot_std_scatter(mdf, "Row", "Mass corrected d 18O/16O(SMOW)",
      "Drift correction - Oxygen", "Row", "Mass corr d18O",
      exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_o),
      slope = res$Drift_O_slope, intercept = res$Drift_O_intercept, r2 = res$Drift_O_r2)
  })
  output$q_mass_check_c <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Mass corrected d 13C/12C" %in% names(mdf),
                  "Need international standards to fit the correction."))
    keep <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough inhouse standards left after removals."))
    plot_std_scatter(keep, "Area All", "Mass corrected d 13C/12C",
      "Mass check - Carbon", "Area All", "Mass corr d13C")
  })
  output$q_mass_check_o <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Mass corrected d 18O/16O(SMOW)" %in% names(mdf),
                  "Need international standards to fit the correction."))
    keep <- mdf[mdf$outlier_O != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough inhouse standards left after removals."))
    plot_std_scatter(keep, "Area All", "Mass corrected d 18O/16O(SMOW)",
      "Mass check - Oxygen", "Area All", "Mass corr d18O")
  })
  output$q_drift_check_c <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Drift corrected d 13C/12C" %in% names(mdf),
                  "Need international standards to fit the correction."))
    keep <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough inhouse standards left after removals."))
    plot_std_scatter(keep, "Row", "Drift corrected d 13C/12C",
      "Drift check - Carbon", "Row", "Drift corr d13C")
  })
  output$q_drift_check_o <- renderPlot({
    res <- preview(); mdf <- res$Mass_df
    validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
    validate(need("Drift corrected d 18O/16O(SMOW)" %in% names(mdf),
                  "Need international standards to fit the correction."))
    keep <- mdf[mdf$outlier_O != "Yes", , drop = FALSE]
    validate(need(nrow(keep) > 1, "Not enough inhouse standards left after removals."))
    plot_std_scatter(keep, "Row", "Drift corrected d 18O/16O(SMOW)",
      "Drift check - Oxygen", "Row", "Drift corr d18O")
  })
  # ----- TAB 4: coefficients table -----
  output$coef_table <- renderTable({
    res <- corrected()
    validate(need(!is.null(res$C_slope), "Upload a raw file first."))
    data.frame(
      Step = c("International C", "International O",
               "Mass effect C", "Mass effect O",
               "Drift C", "Drift O"),
      Slope = c(res$C_slope, res$O_slope,
                res$Mass_C_slope, res$Mass_O_slope,
                res$Drift_C_slope, res$Drift_O_slope),
      Intercept = c(res$C_intercept, res$O_intercept,
                    res$Mass_C_intercept, res$Mass_O_intercept,
                    res$Drift_C_intercept, res$Drift_O_intercept),
      R2 = c(res$C_r2, res$O_r2,
             res$Mass_C_r2, res$Mass_O_r2,
             res$Drift_C_r2, res$Drift_O_r2)
    )
  }, digits = 5)
  # ----- TAB 5: samples table (DT) -----
  msg_notran <- "Upload a raw file first."
  output$sample_table <- renderDT({
    res <- corrected()
    sdf <- res$Sample_df
    validate(need(!is.null(sdf) && nrow(sdf) > 0, msg_notran))
    sdf <- pick_cols(sdf, export_sample_cols)
    style_corr_dt(sdf, c(
      "Drift corrected d 13C/12C",
      "Drift corrected d 18O/16O(SMOW)",
      "Drift corrected d 18O/16O(PDB)"),
      red_col = "Possibly bad sample", easy_hscroll = TRUE)
  })
  # ----- flags text in sidebar -----
  output$flags <- renderText({
    rd <- raw_data()
    msgs <- character(0)
    if (length(rd$outlier) > 0)
      msgs <- c(msgs, paste0('Rows with >6 peaks: ', paste(rd$outlier, collapse = ', ')))
    if (length(rd$outlier2) > 0)
      msgs <- c(msgs, paste0('Rows with 4-5 peaks: ', paste(rd$outlier2, collapse = ', ')))
    if (length(rd$outlier3) > 0)
      msgs <- c(msgs, paste0('Rows with only 3 peaks: ', paste(rd$outlier3, collapse = ', ')))
    if (length(msgs) == 0) 'No peak-count anomalies detected.' else paste(msgs, collapse = '
')
  })

  observeEvent(input$download_xlsx, {
    res <- tryCatch(corrected(), error = function(e) NULL)
    if (is.null(res)) {
      showNotification("Upload a raw file first.", type = "warning")
      return()
    }
    showNotification("Preparing Excel file…", duration = 3, type = "message")
    tryCatch({
      coef_df <- try(build_coef_df(res), silent = TRUE)
      if (inherits(coef_df, "try-error")) coef_df <- data.frame(Correction = character(0))
      wb <- build_workbook(res, get_std_values(), coef_df)
      on.exit(clear_embed_tmp(), add = TRUE)
      send_xlsx_to_browser(session, xlsx_filename(input), wb)
    }, error = function(e) {
      showNotification(paste("Could not save Excel file:", conditionMessage(e)),
                       type = "error", duration = 10)
    })
  })


  })
}

