if (!exists("finalize_std_export", mode = "function", inherits = TRUE)) {
  finalize_std_export <- function(df, corrected_cols) {
    if (is.null(df) || nrow(df) == 0) return(df)
    if (!"Comment" %in% names(df)) df[["Comment"]] <- NA_character_
    is_out <- if ("outlier" %in% names(df)) df$outlier == "Yes" else rep(FALSE, nrow(df))
    if (!any(is_out)) return(df)
    blank <- intersect(corrected_cols, names(df))
    df[is_out, blank] <- NA
    empty_cmt <- is.na(df[["Comment"]]) | trimws(as.character(df[["Comment"]])) == ""
    df[["Comment"]][is_out & empty_cmt] <- "Standard removed"
    rbind(df[!is_out, , drop = FALSE], df[is_out, , drop = FALSE])
  }
}

if (!exists("int_to_col_ref", mode = "function", inherits = TRUE)) {
  int_to_col_ref <- function(n) {
    out <- ""
    while (n > 0) {
      r <- (n - 1) %% 26
      out <- paste0(LETTERS[r + 1], out)
      n <- (n - r - 1) %/% 26
    }
    out
  }
}

if (!exists("calculate_col_widths", mode = "function", inherits = TRUE)) {
  calculate_col_widths <- function(df) {
    if (is.null(df) || ncol(df) == 0) return(numeric(0))
    data_widths <- vapply(df, function(col) {
      w <- nchar(as.character(col))
      w <- w[is.finite(w)]
      if (length(w) == 0) 0L else max(w)
    }, integer(1))
    name_widths <- nchar(names(df))
    pmax(8, pmin(45, pmax(data_widths, name_widths + 3)))
  }
}

