# ------------------------------------------------------------------
# Port process_dataset / process_flash_tcd from Rmd Load data
# ------------------------------------------------------------------
process_dataset <- function(df) {
  unique_rows <- unique(df$Row)
  processed_list <- list()
  for (row_id in unique_rows) {
    subset_df <- df[df$Row == row_id, ]
    rows_10 <- !apply(subset_df[, 10, drop = FALSE], 1, function(x) all(is.na(x)))
    if (sum(rows_10) == 3) {
      row_to_add <- subset_df[1, ]
      new_row <- row_to_add
      subset_df <- rbind(subset_df[1, ], new_row, subset_df[2:nrow(subset_df), ])
      if (nrow(subset_df) >= 4 && !subset_df[4, "Identifier 1"] %in% c("BLANK", "NBS18", "NBS 18")) {
        subset_df[4, 4] <- "No N sample peak"
      }
    }
    rows_11 <- !apply(subset_df[, 11, drop = FALSE], 1, function(x) all(is.na(x)))
    if (sum(rows_11) == 2) {
      last_row <- subset_df[nrow(subset_df), ]
      new_row <- last_row
      subset_df <- rbind(subset_df, new_row)
      if (nrow(subset_df) >= 5 && !subset_df[5, "Identifier 1"] %in% c("BLANK", "N2", "N 2")) {
        subset_df[5, 4] <- "No C sample peak"
      }
    }
    if (sum(rows_11) > 3) {
      subset_df <- subset_df[!(rows_11 & subset_df$`Area All` < 1), ]
    }
    processed_list[[as.character(row_id)]] <- subset_df
  }
  do.call(rbind, processed_list)
}

process_flash_tcd <- function(df) {
  unique_rows <- unique(df$Row)
  processed_list <- list()
  for (row_id in unique_rows) {
    subset_df <- df[df$Row == row_id, ]
    above_150 <- any(subset_df$`Rt Flash TCD` >= 201 & subset_df$`Rt Flash TCD` <= 300, na.rm = TRUE)
    below_200 <- any(subset_df$`Rt Flash TCD` >= 100 & subset_df$`Rt Flash TCD` <= 200, na.rm = TRUE)
    has_na <- any(is.na(subset_df$`Rt Flash TCD`))
    create_new_row <- function(rt_value) {
      new_row <- subset_df[1, ]
      new_row[5:9] <- NA
      new_row$`Rt Flash TCD` <- rt_value
      new_row
    }
    if (!above_150) subset_df <- rbind(subset_df, create_new_row(227))
    if (!below_200) subset_df <- rbind(subset_df, create_new_row(126))
    if (!has_na)    subset_df <- rbind(subset_df, create_new_row(NA))
    subset_df <- subset_df[seq_len(min(3, nrow(subset_df))), ]
    processed_list[[as.character(row_id)]] <- subset_df
  }
  do.call(rbind, processed_list)
}

# N|C wide reshape (Rmd Formatting): odd rows = N peak, even = C peak
reshape_nc_pair <- function(df) {
  if (is.null(df) || nrow(df) == 0) {
    return(df[0, , drop = FALSE])
  }
  df1 <- df |>
    mutate(row_num = row_number()) |>
    filter(row_num %% 2 == 0) |>
    select(-row_num) |>
    select(-c(1:4, 7:10)) |>
    rename(`Sample Dilution C` = 1, `Area All C` = 2)
  df2 <- df |>
    mutate(row_num = row_number()) |>
    filter(row_num %% 2 != 0) |>
    select(-row_num) |>
    select(-c(11:15)) |>
    rename(`Sample Dilution N` = 5, `Area All N` = 6) |>
    mutate(across(3:10, ~ ifelse(`Identifier 1` == "BLANK", NA, .)))
  cbind(df2, df1)
}

na_mean <- function(x) {
  m <- mean(x, na.rm = TRUE)
  if (is.na(m)) 0 else m
}

# Rmd blank mass-balance (including quirks for which blank pool is used)
blank_correct_delta <- function(area, delta, blank_area, blank_delta) {
  ba <- na_mean(blank_area)
  bd <- na_mean(blank_delta)
  (area * delta - ba * bd) / (area - ba)
}

