format_thermo_export <- function(res) {
  idf <- res$International_df
  mdf <- res$Mass_df
  sdf <- res$Sample_df

  if (!is.null(idf) && nrow(idf) > 0) {
    if (is.null(idf[["Plot ID"]]))
      idf[["Plot ID"]] <- if (!is.null(idf[["Row number"]])) idf[["Row number"]] else seq_len(nrow(idf))
    # BLANK rows (no Plot ID from fit set) keep NA Plot ID
    idf <- finalize_std_export(idf, intl_corrected_cols_ea)
    idf <- pick_cols(idf, export_intl_cols_ea)
  }
  if (!is.null(mdf) && nrow(mdf) > 0) {
    if (is.null(mdf[["Plot ID"]])) {
      mdf[["Plot ID"]] <- if (!is.null(mdf[["Row number"]])) mdf[["Row number"]] else NA_integer_
    }
    # Don't treat blank rows as outliers for finalize
    is_blank <- toupper(as.character(mdf$`Identifier 1`)) == "BLANK"
    mdf_std <- mdf[!is_blank, , drop = FALSE]
    mdf_blk <- mdf[is_blank, , drop = FALSE]
    mdf_std <- finalize_std_export(mdf_std, mass_corrected_cols_ea)
    mdf <- rbind(mdf_blk, mdf_std)
    mdf <- pick_cols(mdf, export_mass_cols_ea)
  }
  if (!is.null(sdf) && nrow(sdf) > 0) {
    sdf <- pick_cols(sdf, export_sample_cols_ea)
  }
  list(Sample_df = sdf, International_df = idf, Mass_df = mdf)
}

build_thermo_coef_df <- function(r) {
  data.frame(
    Correction = c("International N", "Mass N", "Drift N",
                   "International C", "Mass C", "Drift C"),
    Slope = c(r$N_slope %||% NA, r$Mass_N_slope %||% NA, r$Drift_N_slope %||% NA,
              r$C_slope %||% NA, r$Mass_C_slope %||% NA, r$Drift_C_slope %||% NA),
    Intercept = c(r$N_intercept %||% NA, r$Mass_N_intercept %||% NA, r$Drift_N_intercept %||% NA,
                  r$C_intercept %||% NA, r$Mass_C_intercept %||% NA, r$Drift_C_intercept %||% NA),
    R_squared = c(r$N_r2 %||% NA, r$Mass_N_r2 %||% NA, r$Drift_N_r2 %||% NA,
                  r$C_r2 %||% NA, r$Mass_C_r2 %||% NA, r$Drift_C_r2 %||% NA),
    stringsAsFactors = FALSE
  )
}

sheet_tab_colours_ea <- c(
  Samples = "green",
  International_standards = "blue",
  Inhouse_standards = "orange",
  Coefficients = "grey"
)

build_thermo_workbook <- function(res) {
  clear_embed_tmp()
  exp <- format_thermo_export(res)
  Sample_df <- exp$Sample_df
  International_df <- exp$International_df
  Mass_df <- exp$Mass_df
  coef_df <- build_thermo_coef_df(res)

  wb <- createWorkbook()
  hs <- createStyle(fontSize = 11, fontColour = "#000000",
                    fgFill = "grey", textDecoration = "bold")
  highlight  <- createStyle(fontColour = "#000000", bgFill = "green")
  highlight2 <- createStyle(fontColour = "#000000", bgFill = "red")

  addSheet <- function(name, dat) {
    addWorksheet(wb, name, tabColour = unname(sheet_tab_colours_ea[[name]]))
    writeData(wb, name, dat, headerStyle = hs, withFilter = TRUE)
    if (!is.null(dat) && ncol(dat) > 0)
      setColWidths(wb, name, cols = seq_len(ncol(dat)), widths = calculate_col_widths(dat))
  }
  addSheet("Samples", Sample_df)
  addSheet("International_standards", International_df)
  addSheet("Inhouse_standards", Mass_df)
  addSheet("Coefficients", coef_df)

  cf_green <- function(sheet, dat, col_names) {
    n <- nrow(dat)
    if (is.null(dat) || n == 0) return(NULL)
    for (j in which(names(dat) %in% col_names)) {
      colref <- int_to_col_ref(j)
      conditionalFormatting(wb, sheet, cols = j, rows = 2:(n + 1),
                            rule = paste0("ISNUMBER($", colref, "2)"), style = highlight)
    }
  }
  cf_red <- function(sheet, dat, flag_col) {
    n <- nrow(dat)
    j <- match(flag_col, names(dat))
    if (is.null(dat) || n == 0 || is.na(j)) return(NULL)
    conditionalFormatting(wb, sheet, cols = 1:ncol(dat), rows = 2:(n + 1),
                          rule = paste0("$", int_to_col_ref(j), "2>0"), style = highlight2)
  }

  cf_green("Samples", Sample_df, c(
    "Drift corrected d 15N/14N", "Drift corrected d 13C/12C", "C/N"))
  cf_red("Samples", Sample_df, "Possibly bad sample")
  cf_green("International_standards", International_df, c(
    "Measured-TrueN", "Measured-TrueC",
    "International corrected d 15N/14N", "International corrected d 13C/12C"))
  cf_green("Inhouse_standards", Mass_df, c(
    "Measured-TrueN", "Measured-TrueC",
    "Drift corrected d 15N/14N", "Drift corrected d 13C/12C", "C/N"))

  # Embed plots at Rmd positions
  idf <- res$International_df
  mdf <- res$Mass_df
  if (!is.null(idf) && nrow(idf) > 0) {
    if (!is.null(res$C_slope)) {
      embed_ggplot(wb, "International_standards",
        plot_wb_scatter(idf, "Blank corrected d 13C/12C", "True d 13C/12C",
          "International correction - Carbon", "Blank corr d13C", "True d13C",
          res$C_slope, res$C_intercept, res$C_r2, excl_flag = "outlier_C"),
        startRow = 20, startCol = 12)
      keep_i_c <- idf[idf$outlier_C != "Yes", , drop = FALSE]
      if (nrow(keep_i_c) > 1) {
        mC2 <- lm(keep_i_c$`True d 13C/12C` ~ keep_i_c$`International corrected d 13C/12C`)
        embed_ggplot(wb, "International_standards",
          plot_wb_scatter(keep_i_c, "International corrected d 13C/12C", "True d 13C/12C",
            "International check - Carbon", "Intl corr d13C", "True d13C",
            unname(coef(mC2)[2]), unname(coef(mC2)[1]), summary(mC2)$r.squared,
            include_outliers = FALSE),
          startRow = 41, startCol = 12)
      }
    }
    if (!is.null(res$N_slope)) {
      embed_ggplot(wb, "International_standards",
        plot_wb_scatter(idf, "Blank corrected d 15N/14N", "True d 15N/14N",
          "International correction - Nitrogen", "Blank corr d15N", "True d15N",
          res$N_slope, res$N_intercept, res$N_r2, excl_flag = "outlier_N"),
        startRow = 20, startCol = 6)
      keep_i_n <- idf[idf$outlier_N != "Yes", , drop = FALSE]
      if (nrow(keep_i_n) > 1) {
        mN2 <- lm(keep_i_n$`True d 15N/14N` ~ keep_i_n$`International corrected d 15N/14N`)
        embed_ggplot(wb, "International_standards",
          plot_wb_scatter(keep_i_n, "International corrected d 15N/14N", "True d 15N/14N",
            "International check - Nitrogen", "Intl corr d15N", "True d15N",
            unname(coef(mN2)[2]), unname(coef(mN2)[1]), summary(mN2)$r.squared,
            include_outliers = FALSE),
          startRow = 41, startCol = 6)
      }
    }
  }

  if (!is.null(mdf) && nrow(mdf) > 1 && !is.null(res$Mass_C_slope)) {
    mdf_plot <- mdf[toupper(as.character(mdf$`Identifier 1`)) != "BLANK", , drop = FALSE]
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf_plot, "Area All C", "International corrected d 13C/12C",
        "Mass correction - Carbon", "Area All C", "Intl corr d13C",
        res$Mass_C_slope, res$Mass_C_intercept, res$Mass_C_r2, excl_flag = "outlier_C"),
      startRow = 20, startCol = 26)
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf_plot, "Area All N", "International corrected d 15N/14N",
        "Mass correction - Nitrogen", "Area All N", "Intl corr d15N",
        res$Mass_N_slope, res$Mass_N_intercept, res$Mass_N_r2, excl_flag = "outlier_N"),
      startRow = 20, startCol = 11)
    keep_m_c <- mdf_plot[mdf_plot$outlier_C != "Yes", , drop = FALSE]
    keep_m_n <- mdf_plot[mdf_plot$outlier_N != "Yes", , drop = FALSE]
    if (nrow(keep_m_c) > 1) {
      mMC2 <- lm(keep_m_c$`Mass corrected d 13C/12C` ~ keep_m_c$`Area All C`)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Area All C", "Mass corrected d 13C/12C",
          "Mass check - Carbon", "Area All C", "Mass corr d13C",
          unname(coef(mMC2)[2]), unname(coef(mMC2)[1]), summary(mMC2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 26)
    }
    if (nrow(keep_m_n) > 1) {
      mMN2 <- lm(keep_m_n$`Mass corrected d 15N/14N` ~ keep_m_n$`Area All N`)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_n, "Area All N", "Mass corrected d 15N/14N",
          "Mass check - Nitrogen", "Area All N", "Mass corr d15N",
          unname(coef(mMN2)[2]), unname(coef(mMN2)[1]), summary(mMN2)$r.squared,
          include_outliers = FALSE),
        startRow = 41, startCol = 11)
    }
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf_plot, "Row", "Mass corrected d 13C/12C",
        "Drift correction - Carbon", "Row", "Mass corr d13C",
        res$Drift_C_slope, res$Drift_C_intercept, res$Drift_C_r2, excl_flag = "outlier_C"),
      startRow = 61, startCol = 26)
    embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf_plot, "Row", "Mass corrected d 15N/14N",
        "Drift correction - Nitrogen", "Row", "Mass corr d15N",
        res$Drift_N_slope, res$Drift_N_intercept, res$Drift_N_r2, excl_flag = "outlier_N"),
      startRow = 61, startCol = 11)
    if (nrow(keep_m_c) > 1) {
      mDC2 <- lm(keep_m_c$`Drift corrected d 13C/12C` ~ keep_m_c$Row)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Row", "Drift corrected d 13C/12C",
          "Drift check - Carbon", "Row", "Drift corr d13C",
          unname(coef(mDC2)[2]), unname(coef(mDC2)[1]), summary(mDC2)$r.squared,
          include_outliers = FALSE),
        startRow = 81, startCol = 26)
    }
    if (nrow(keep_m_n) > 1) {
      mDN2 <- lm(keep_m_n$`Drift corrected d 15N/14N` ~ keep_m_n$Row)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_n, "Row", "Drift corrected d 15N/14N",
          "Drift check - Nitrogen", "Row", "Drift corr d15N",
          unname(coef(mDN2)[2]), unname(coef(mDN2)[1]), summary(mDN2)$r.squared,
          include_outliers = FALSE),
        startRow = 81, startCol = 11)
    }

    # Optional TCD plots
    if (isTRUE(res$has_tcd) &&
        all(c("rArea Flash TCD C", "µg C/cup") %in% names(mdf_plot))) {
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(mdf_plot, "rArea Flash TCD C", "µg C/cup",
          "Correction - CN (C)", "Area Flash TCD C", "µg C/cup",
          res$TCD_C_slope, 0, res$TCD_C_r2, excl_flag = "outlier_C"),
        startRow = 20, startCol = 30)
      embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(mdf_plot, "rArea Flash TCD N", "µg N/cup",
          "Correction - CN (N)", "Area Flash TCD N", "µg N/cup",
          res$TCD_N_slope, 0, res$TCD_N_r2, excl_flag = "outlier_N"),
        startRow = 20, startCol = 15)
    }
  }

  try(freezePane(wb, "Samples", firstActiveRow = 2, firstActiveCol = 4), silent = TRUE)
  try(freezePane(wb, "International_standards", firstActiveRow = 2, firstActiveCol = 4), silent = TRUE)
  try(freezePane(wb, "Inhouse_standards", firstActiveRow = 2, firstActiveCol = 4), silent = TRUE)
  wb
}

