# ---- local helpers (use common.R equivalents if already loaded) ----
if (!exists("clean_idx", mode = "function")) {
  clean_idx <- function(idx, n) {
    idx <- as.integer(idx)
    idx[!is.na(idx) & idx >= 1 & idx <= n]
  }
}

if (!exists("decimal_places", mode = "function")) {
  decimal_places <- function(x, fallback = 3L) {
    x <- as.numeric(x)
    x <- x[is.finite(x)]
    if (!length(x)) return(as.integer(fallback))
    nd <- vapply(x, function(v) {
      s <- sub("0+$", "", sprintf("%.10f", abs(v)))
      s <- sub("\\.$", "", s)
      if (!grepl(".", s, fixed = TRUE)) 0L else nchar(strsplit(s, ".", fixed = TRUE)[[1]][2])
    }, integer(1))
    nd <- nd[nd > 0]
    if (!length(nd)) return(as.integer(fallback))
    as.integer(names(sort(table(nd), decreasing = TRUE))[1])
  }
}

if (!exists("pick_cols", mode = "function")) {
  pick_cols <- function(df, cols) {
    for (nm in cols) if (!nm %in% names(df)) df[[nm]] <- NA
    df[, cols, drop = FALSE]
  }
}

if (!exists("finalize_std_export", mode = "function")) {
  finalize_std_export <- function(df, corrected_cols) {
    if (is.null(df) || nrow(df) == 0) return(df)
    if (!"Comment" %in% names(df)) df[["Comment"]] <- NA_character_
    is_out <- if ("outlier" %in% names(df)) df$outlier == "Yes" else rep(FALSE, nrow(df))
    if (!any(is_out)) return(df)
    blank <- intersect(corrected_cols, names(df))
    df[is_out, blank] <- NA
    empty_cmt <- is.na(df[["Comment"]]) | trimws(as.character(df[["Comment"]])) == ""
    df[["Comment"]][is_out & empty_cmt] <- "Standard removed"
    rbind(df[!is_out, , drop = FALSE], df[is_out, , drop = FALSE])
  }
}

if (!exists("int_to_col_ref", mode = "function")) {
  int_to_col_ref <- function(n) {
    out <- ""
    while (n > 0) {
      r <- (n - 1) %% 26
      out <- paste0(LETTERS[r + 1], out)
      n <- (n - r - 1) %/% 26
    }
    out
  }
}

if (!exists("calculate_col_widths", mode = "function")) {
  calculate_col_widths <- function(df) {
    if (is.null(df) || ncol(df) == 0) return(numeric(0))
    data_widths <- vapply(df, function(col) {
      w <- nchar(as.character(col))
      w <- w[is.finite(w)]
      if (length(w) == 0) 0L else max(w)
    }, integer(1))
    name_widths <- nchar(names(df))
    pmax(8, pmin(45, pmax(data_widths, name_widths + 3)))
  }
}

if (!exists("eq_label", mode = "function")) {
  eq_label <- function(slope, intercept, r2, digits = 5) {
    paste0("y = ", round(slope, digits), " x + ", round(intercept, digits),
           "  R-squared=", round(r2, digits))
  }
}

if (!exists("style_corr_dt", mode = "function")) {
  style_corr_dt <- function(df, green_cols, red_col = NULL) {
    dt <- datatable(df, options = list(
      scrollX = TRUE,
      pageLength = 100,
      lengthMenu = list(c(25, 50, 100, -1), c("25", "50", "100", "All"))
    ), rownames = FALSE)
    for (col in intersect(green_cols, names(df))) {
      dt <- formatStyle(dt, col, backgroundColor = "#C6EFCE")
    }
    if (!is.null(red_col) && red_col %in% names(df)) {
