sercon_embed_ggplot <- function(wb, sheet, plot, startRow, startCol,
                                width = 6, height = 4, dpi = 150) {
  tryCatch({
    tf <- tempfile(fileext = ".png")
    ggsave(tf, plot, width = width, height = height, dpi = dpi, limitsize = FALSE)
    .sercon_embed_env$files <- c(.sercon_embed_env$files, tf)
    insertImage(wb, sheet, tf, startRow = startRow, startCol = startCol,
                width = width, height = height, units = "in")
  }, error = function(e) {
    warning("Could not embed plot on sheet ", sheet, ": ", conditionMessage(e),
            call. = FALSE)
    invisible(NULL)
  })
}

sercon_clear_embed_tmp <- function() {
  if (length(.sercon_embed_env$files)) unlink(.sercon_embed_env$files)
  .sercon_embed_env$files <- character(0)
}

