    sidebarLayout(
      sidebarPanel(
        width = 3,
        drop_file_input(ns("file"), "Raw Sercon .xls", accept = ".xls"),
        drop_file_input(ns("template_1"), "Template 1 (.xlsx, optional)", accept = c(".xlsx")),
        drop_file_input(ns("template_2"), "Template 2 (.xlsx, optional; wells matched as AA1, BB1, …)",
                  accept = c(".xlsx")),
        checkboxInput(ns("blank_correct_n"),
                      "Blank-correct nitrogen (off = default passthrough)",
                      value = FALSE),
