    tags$script(HTML("
(function () {
  function saveClientFile(msg) {
    var bin = atob(msg.b64);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    var blob = new Blob([bytes], { type: msg.mime || 'application/octet-stream' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = msg.filename || 'download.xlsx';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 2000);
  }
  function assignFiles(input, files) {
    if (!input || !files || !files.length) return;
    try {
      var dt = new DataTransfer();
      dt.items.add(files[0]);
      input.files = dt.files;
    } catch (err) {
      input.files = files;
    }
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }
  function wireDropzones(root) {
    var zones = (root || document).querySelectorAll('.iso-dropzone');
    for (var i = 0; i < zones.length; i++) {
      var zone = zones[i];
      if (zone.dataset.wired === '1') continue;
      zone.dataset.wired = '1';
      var input = zone.querySelector('input[type=file]');
      if (!input) continue;
      zone.addEventListener('dragenter', function (e) {
        e.preventDefault(); e.stopPropagation(); this.classList.add('iso-drop-hover');
      });
      zone.addEventListener('dragover', function (e) {
        e.preventDefault(); e.stopPropagation(); this.classList.add('iso-drop-hover');
      });
      zone.addEventListener('dragleave', function (e) {
        e.preventDefault(); e.stopPropagation(); this.classList.remove('iso-drop-hover');
      });
      zone.addEventListener('drop', function (e) {
        e.preventDefault(); e.stopPropagation();
        this.classList.remove('iso-drop-hover');
        var inp = this.querySelector('input[type=file]');
        assignFiles(inp, e.dataTransfer && e.dataTransfer.files);
      });
    }
  }
  function visibleEl(sel) {
    var nodes = document.querySelectorAll(sel);
    for (var i = 0; i < nodes.length; i++) {
      var r = nodes[i].getBoundingClientRect();
      if (r.width > 2 && r.height > 2) return nodes[i];
    }
    return null;
  }
  function clickTab(label) {
    var links = document.querySelectorAll('.nav-tabs a, .nav-tabs .nav-link');
    for (var i = 0; i < links.length; i++) {
      var t = (links[i].textContent || '').replace(/^\\s+|\\s+$/g, '');
      if (t.indexOf(label) === 0 && links[i].offsetParent !== null) {
        links[i].click();
        return links[i];
      }
    }
    return null;
  }
  var guide = { i: 0, steps: [], overlay: null, card: null };
  function guideSteps() {
    return [
      { sel: '[data-guide=\"instrument\"]', title: '1. Choose instrument',
        text: 'Pick GasBench (C/O), Thermo EA (C/N + TCD) or Sercon EA. Same flow as the lab notebooks.' },
      { sel: '[data-guide=\"file\"]', title: '2. Add the raw file',
        text: 'Drop the raw excel here or click Browse.' },
      { tab: 'International', sels: ['[data-guide=\"intl-outliers\"]', '[data-guide=\"intl-table\"]'],
        title: '3. International outliers',
        text: 'Look at the International table. Values do not need to be close to the true value, as long as standards of the same type do not vary too much from each other. Tick only International standards in the left Exclude outliers list if one is clearly off.' },
      { tab: 'Inhouse', sels: ['[data-guide=\"inhouse-outliers\"]', '[data-guide=\"inhouse-review\"]'],
        title: '4. Inhouse outliers',
        text: 'Look at the Inhouse table and the mass/drift graphs. Points should be relatively close to each other, or not too far from the blue fit line. Tick only Inhouse standards in the left Exclude outliers list if they sit well off the line.' },
      { tab: 'Inhouse', sel: '[data-guide=\"drift-check\"]', title: '5. Drift check',
        text: 'Review the drift-check plots. They drop outliers and show remaining variation after correction — use them to judge whether the run is stable.' },
      { tab: 'Samples', sel: '[data-guide=\"samples-table\"]', title: '6. Samples',
        text: 'Open the Samples tab and scan the corrected values. Check that they look reasonable before you download.' },
      { sel: '[data-guide=\"download\"]', title: '7. Download',
        text: 'Download the corrected Excel workbook when you are happy with the tables.' }
    ];
  }
  function stepSels(step) {
    if (step.sels && step.sels.length) return step.sels;
    return step.sel ? [step.sel] : [];
  }
  function placeGuideCard(targets) {
    var card = guide.card;
    if (!card) return;
    var cw = Math.min(360, window.innerWidth - 24);
    var ch = card.offsetHeight || 200;
    var pad = 14;
    var boxes = [];
    for (var i = 0; i < targets.length; i++) boxes.push(targets[i].getBoundingClientRect());
    function blocked(l, t) {
      var r = l + cw, b = t + ch;
      if (l < 8 || t < 8 || r > window.innerWidth - 8 || b > window.innerHeight - 8) return true;
      for (var j = 0; j < boxes.length; j++) {
        var x = boxes[j];
        if (l < x.right + pad && r > x.left - pad && t < x.bottom + pad && b > x.top - pad) return true;
      }
      return false;
    }
    var p = boxes[0] || { left: 24, right: 24, top: 80, bottom: 80 };
    var low = p.bottom > window.innerHeight * 0.5;
    var opts = low ? [
      { l: Math.min(window.innerWidth - cw - 16, Math.max(16, p.right + pad)), t: Math.max(16, p.top - ch) },
      { l: Math.max(16, p.left), t: Math.max(16, p.top - ch - pad) },
      { l: 16, t: 16 },
      { l: window.innerWidth - cw - 16, t: 16 }
    ] : [
      { l: Math.min(window.innerWidth - cw - 16, Math.max(16, p.right + pad)), t: Math.max(16, p.top) },
      { l: Math.max(16, p.left), t: p.bottom + pad },
      { l: Math.max(16, p.left), t: Math.max(16, p.top - ch - pad) },
      { l: 16, t: 16 },
      { l: window.innerWidth - cw - 16, t: 16 }
    ];
    var pick = null;
    for (var k = 0; k < opts.length; k++) {
      if (!blocked(opts[k].l, opts[k].t)) { pick = opts[k]; break; }
    }
    if (!pick) pick = { l: 16, t: 16 };
    card.style.top = pick.t + 'px';
    card.style.left = pick.l + 'px';
  }
  function endGuide() {
    if (guide.overlay) guide.overlay.remove();
    if (guide.card) guide.card.remove();
    var spots = document.querySelectorAll('.iso-guide-spot');
    for (var i = 0; i < spots.length; i++) spots[i].classList.remove('iso-guide-spot');
    guide.overlay = null;
    guide.card = null;
  }
  function showGuideStep() {
    var steps = guide.steps;
    if (guide.i < 0 || guide.i >= steps.length) { endGuide(); return; }
    var step = steps[guide.i];
    if (step.tab) clickTab(step.tab);
    var sels = stepSels(step);
    var spots = [];
    for (var s = 0; s < sels.length; s++) {
      var found = visibleEl(sels[s]);
      if (found) spots.push(found);
    }
    if (step.tab && !spots.length && !step._retried) {
      step._retried = true;
      setTimeout(function () { step._retried = false; showGuideStep(); }, 160);
      return;
    }
    document.querySelectorAll('.iso-guide-spot').forEach(function (n) {
      n.classList.remove('iso-guide-spot');
    });
    var el = spots[0] || null;
    for (var h = 0; h < spots.length; h++) spots[h].classList.add('iso-guide-spot');
    if (el) {
      var nearBottom = /download/i.test(sels.join(' '));
      el.scrollIntoView({ block: nearBottom ? 'nearest' : 'center', behavior: 'smooth' });
    }
    if (!guide.overlay) {
      guide.overlay = document.createElement('div');
      guide.overlay.className = 'iso-guide-overlay';
      guide.overlay.addEventListener('click', endGuide);
      document.body.appendChild(guide.overlay);
    }
    if (!guide.card) {
      guide.card = document.createElement('div');
      guide.card.className = 'iso-guide-card';
      document.body.appendChild(guide.card);
    }
    guide.card.innerHTML = '<h4>' + step.title + '</h4><p>' + step.text +
      '</p><div class=\"iso-guide-actions\">' +
      '<button type=\"button\" class=\"btn btn-default btn-sm\" id=\"iso-guide-back\">Back</button>' +
      '<button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"iso-guide-next\">' +
      (guide.i === steps.length - 1 ? 'Done' : 'Next') + '</button>' +
      '<button type=\"button\" class=\"btn btn-link btn-sm\" id=\"iso-guide-skip\">Close</button></div>' +
      '<div style=\"font-size:12px;color:#666;margin-top:8px;\">Step ' + (guide.i + 1) + ' of ' + steps.length + '</div>';
    placeGuideCard(spots);
    setTimeout(function () { placeGuideCard(spots); }, 80);
    document.getElementById('iso-guide-next').onclick = function (e) {
      e.stopPropagation(); guide.i += 1; showGuideStep();
    };
    document.getElementById('iso-guide-back').onclick = function (e) {
      e.stopPropagation(); if (guide.i > 0) guide.i -= 1; showGuideStep();
    };
    document.getElementById('iso-guide-skip').onclick = function (e) {
      e.stopPropagation(); endGuide();
    };
    guide.card.onclick = function (e) { e.stopPropagation(); };
  }
  function instrumentChosen() {
    var radios = document.querySelectorAll('input[name=\"instrument\"]:checked');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].value) return true;
    }
    return false;
  }
  function fileChosen() {
    var inputs = document.querySelectorAll('[data-guide=\"file\"] input[type=file]');
    for (var i = 0; i < inputs.length; i++) {
      if (inputs[i].offsetParent === null) continue;
      if (inputs[i].files && inputs[i].files.length) return true;
    }
    return false;
  }
  function activeTabLabel() {
    var links = document.querySelectorAll('.nav-tabs li.active a, .nav-tabs .active > a, .nav-tabs .nav-link.active');
    for (var i = 0; i < links.length; i++) {
      if (links[i].offsetParent !== null) return (links[i].textContent || '').replace(/^\\s+|\\s+$/g, '');
    }
    return '';
  }
  function reachedStep() {
    if (!instrumentChosen()) return 0;
    if (!fileChosen()) return 1;
    var tab = activeTabLabel();
    if (/Coefficient/i.test(tab)) return 6;
    if (/Sample/i.test(tab)) return 5;
    if (/Inhouse/i.test(tab)) return 3;
    return 2;
  }
  function guideIsOn() { return !!(guide.card || guide.overlay); }
  function goGuideStep(n) {
    if (!guide.steps.length) guide.steps = guideSteps();
    guide.i = n;
    var tries = 0;
    function paint() {
      tries += 1;
      var step = guide.steps[guide.i];
      if (!step || visibleEl(stepSels(step)[0]) || tries > 25) {
        showGuideStep();
        return;
      }
      setTimeout(paint, 120);
    }
    setTimeout(paint, 80);
  }
  function afterInstrumentChosen() {
    if (!guideIsOn()) return;
    if (guide.i === 0) goGuideStep(1);
  }
  function syncInstrumentChrome() {
    document.body.classList.toggle('iso-in-instrument', instrumentChosen());
  }
  function startGuide() {
    var box = document.getElementById('iso-howto');
    if (box && !instrumentChosen()) box.open = true;
    endGuide();
    guide.steps = guideSteps();
    guide.i = reachedStep();
    showGuideStep();
  }
  window.startIsoGuide = startGuide;
  function wireInstrumentAdvance() {
    var radios = document.querySelectorAll('input[name=\"instrument\"]');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].dataset.guideAdvance === '1') continue;
      radios[i].dataset.guideAdvance = '1';
      radios[i].addEventListener('change', function () {
        if (this.value) afterInstrumentChosen();
      });
    }
    if (document.documentElement.dataset.isoGuideInput === '1') return;
    document.documentElement.dataset.isoGuideInput = '1';
    document.addEventListener('change', function (e) {
      var t = e.target;
      if (t && t.name === 'instrument' && t.value) afterInstrumentChosen();
    }, true);
    document.addEventListener('shiny:inputchanged', function (e) {
      var d = e.detail || {};
      if (d.name === 'instrument' && d.value) afterInstrumentChosen();
      syncInstrumentChrome();
    });
  }
  function wireGuide() {
    var ids = ['iso-guide-start', 'iso-guide-start-top', 'iso-guide-start-bottom'];
    for (var b = 0; b < ids.length; b++) {
      var btn = document.getElementById(ids[b]);
      if (btn && btn.dataset.wired !== '1') {
        btn.dataset.wired = '1';
        btn.addEventListener('click', function (e) { e.preventDefault(); startGuide(); });
      }
    }
    wireInstrumentAdvance();
  }
  function bind() {
    if (window.Shiny && Shiny.addCustomMessageHandler) {
      Shiny.addCustomMessageHandler('save_client_file', saveClientFile);
      wireDropzones(document);
      wireGuide();
      return;
    }
    setTimeout(bind, 50);
  }
  if (document.addEventListener) {
    document.addEventListener('shiny:connected', function () {
      if (window.Shiny && Shiny.addCustomMessageHandler) {
        Shiny.addCustomMessageHandler('save_client_file', saveClientFile);
      }
      wireDropzones(document);
      wireGuide();
    });
    document.addEventListener('DOMContentLoaded', function () {
      wireDropzones(document);
      wireGuide();
    });
  }
  if (window.MutationObserver) {
    new MutationObserver(function () { wireDropzones(document); wireGuide(); syncInstrumentChrome(); })
      .observe(document.documentElement, { childList: true, subtree: true });
  }
  bind();
  syncInstrumentChrome();
})();
"))
  ),
  titlePanel("Isotope lab correction"),
  conditionalPanel(
    condition = "input.instrument == null || input.instrument === ''",
    tags$div(class = "instrument-chooser", `data-guide` = "instrument",
      h3("Choose instrument / workflow"),
