    tags$div(class = "instrument-bar",
      actionLink("back_home", "← Change instrument"),
      textOutput("instrument_label", inline = TRUE),
      tags$button(id = "iso-guide-start-top", type = "button", class = "btn btn-primary",
                  "How to / start interactive guide")
    ),
    hr()
  ),
  conditionalPanel(
    condition = "input.instrument === 'gb'",
    thermo_gb_ui("gb")
  ),
  conditionalPanel(
    condition = "input.instrument === 'ea'",
    thermo_ea_ui("ea")
  ),
  conditionalPanel(
    condition = "input.instrument === 'sercon'",
    sercon_ea_ui("sercon")
  ),
  tags$details(
    id = "iso-howto",
    class = "iso-howto",
    open = NA,
    tags$summary("How to use this app"),
    tags$div(class = "iso-howto-body",
      tags$p(tags$button(id = "iso-guide-start-bottom", type = "button",
                         class = "btn btn-primary btn-sm",
                         "Start interactive guide")),
      tags$ol(
        tags$li(tags$b("Choose instrument"), " — GasBench (C/O), Thermo EA (C/N + Flash TCD), or Sercon EA."),
        tags$li(tags$b("Add the raw file"), " — Drop the raw excel here or click Browse."),
        tags$li(tags$b("International outliers"), " — they do not need to be close to the true value, as long as standards of the same type do not vary too much from each other."),
        tags$li(tags$b("Inhouse outliers"), " — points should be relatively close to each other, or not too far from the blue fit line."),
        tags$li(tags$b("Drift check"), " — review remaining variation after correction."),
        tags$li(tags$b("Samples"), " — scan the corrected sample table."),
        tags$li(tags$b("Download"), " — save the corrected Excel workbook.")
      ),
      tags$p(style = "font-size:13px;color:#555;margin-top:10px;",
             "Sercon: the raw file is a .xls file (not .xlsx). Optional weighing templates (.xlsx) can be dropped under it.")
    )
  )
)

server <- function(input, output, session) {
  # Desktop launcher sets this so closing the browser tab stops R (and the terminal).
  if (isTRUE(getOption("isotope_app.quit_on_close", FALSE))) {
    session$onSessionEnded(function() stopApp())
  }

  if (exists("thermo_gb_server", mode = "function")) thermo_gb_server("gb")
  if (exists("thermo_ea_server", mode = "function")) thermo_ea_server("ea")
  if (exists("sercon_ea_server", mode = "function")) sercon_ea_server("sercon")

  output$instrument_label <- renderText({
    switch(input$instrument %||% "",
      gb = "Thermo GasBench",
      ea = "Thermo EA",
      sercon = "Sercon EA",
      ""
    )
  })

  observeEvent(input$back_home, {
    updateRadioButtons(session, "instrument", selected = character(0))
  })
}

shinyApp(ui, server)
